       throw new RangeError(
         `amountCents must be a non-negative integer (got ${amountCents})`,
       );
     }
   }

   computeDiscountCents(subtotalCents: number): number {
     if (subtotalCents <= 0) return 0;
     return Math.min(this.amountCents, subtotalCents);
   }
