    // tax = floor(1100 * 0.08) = 88
    // shipping = 599
    expect(result.totals.subtotalCents).toBe(1200);
    expect(result.totals.discountCents).toBe(100);
    expect(result.totals.taxCents).toBe(88);
    expect(result.totals.shippingCents).toBe(599);
    expect(result.totals.totalCents).toBe(1100 + 88 + 599);
  });
});

import { describe, it, expect } from "vitest";
import {
  NoDiscountPolicy,
  PercentageDiscountPolicy,
  FixedAmountDiscountPolicy,
  CompositeDiscountPolicy,
} from "../src/pricing.ts";

describe("NoDiscountPolicy", () => {
  const policy = new NoDiscountPolicy();

  it.each([0, 100, 5000, -10])("returns 0 for subtotal %i", (subtotal) => {
    expect(policy.computeDiscountCents(subtotal)).toBe(0);
  });
