describe("PercentageDiscountPolicy", () => {
  describe("constructor validation", () => {
    it.each([-1, 101, NaN, Infinity, -Infinity])(
      "rejects invalid percent %s",
      (percent) => {
        expect(() => new PercentageDiscountPolicy(percent)).toThrow(RangeError);
      },
    );

    it.each([0, 50, 100])("accepts valid percent %i", (percent) => {
      expect(() => new PercentageDiscountPolicy(percent)).not.toThrow();
    });
  });

  describe("computeDiscountCents", () => {
    it("computes 10% of 1000 = 100", () => {
      const policy = new PercentageDiscountPolicy(10);
      expect(policy.computeDiscountCents(1000)).toBe(100);
    });

    it("rounds down to nearest cent", () => {
      const policy = new PercentageDiscountPolicy(33);
      // 33% of 100 = 33.0 → 33
      expect(policy.computeDiscountCents(100)).toBe(33);
      // 33% of 101 = 33.33 → 33
      expect(policy.computeDiscountCents(101)).toBe(33);
    });

    it("returns 0 for zero subtotal", () => {
      const policy = new PercentageDiscountPolicy(50);
      expect(policy.computeDiscountCents(0)).toBe(0);
    });

    it("returns 0 for negative subtotal", () => {
      const policy = new PercentageDiscountPolicy(50);
      expect(policy.computeDiscountCents(-100)).toBe(0);
    });

    it("100% discount equals subtotal", () => {
      const policy = new PercentageDiscountPolicy(100);
      expect(policy.computeDiscountCents(9999)).toBe(9999);
    });

    it("0% discount returns 0", () => {
      const policy = new PercentageDiscountPolicy(0);
      expect(policy.computeDiscountCents(9999)).toBe(0);
    });
  });
});

describe("FixedAmountDiscountPolicy", () => {
  describe("constructor validation", () => {
    it.each([-1, -100, 1.5, NaN])(
      "rejects invalid amountCents %s",
      (amount) => {
        expect(() => new FixedAmountDiscountPolicy(amount)).toThrow(RangeError);
      },
    );

    it("accepts zero", () => {
      expect(() => new FixedAmountDiscountPolicy(0)).not.toThrow();
    });
  });

  describe("computeDiscountCents", () => {
    it("returns fixed amount when subtotal exceeds it", () => {
      const policy = new FixedAmountDiscountPolicy(500);
      expect(policy.computeDiscountCents(1000)).toBe(500);
    });

    it("caps at subtotal when fixed amount exceeds subtotal", () => {
      const policy = new FixedAmountDiscountPolicy(500);
      expect(policy.computeDiscountCents(300)).toBe(300);
    });

    it("returns 0 for zero subtotal", () => {
      const policy = new FixedAmountDiscountPolicy(500);
      expect(policy.computeDiscountCents(0)).toBe(0);
    });

    it("returns 0 for negative subtotal", () => {
      const policy = new FixedAmountDiscountPolicy(500);
      expect(policy.computeDiscountCents(-100)).toBe(0);
    });
  });
});

describe("CompositeDiscountPolicy", () => {
  describe("constructor validation", () => {
    it("rejects empty policies array", () => {
      expect(() => new CompositeDiscountPolicy([])).toThrow(
        "CompositeDiscountPolicy requires at least one policy",
      );
    });
  });

  describe("sum mode", () => {
    it("sums discounts from all policies against original subtotal", () => {
      const p1 = new PercentageDiscountPolicy(10); // 10% of 1000 = 100
      const p2 = new FixedAmountDiscountPolicy(200); // 200
      const composite = new CompositeDiscountPolicy([p1, p2], "sum");
      expect(composite.computeDiscountCents(1000)).toBe(300);
    });

    it("returns 0 for zero subtotal", () => {
      const p1 = new PercentageDiscountPolicy(10);
      const composite = new CompositeDiscountPolicy([p1], "sum");
      expect(composite.computeDiscountCents(0)).toBe(0);
    });

    it("returns 0 for negative subtotal", () => {
      const p1 = new FixedAmountDiscountPolicy(100);
      const composite = new CompositeDiscountPolicy([p1], "sum");
      expect(composite.computeDiscountCents(-50)).toBe(0);
    });

    it("can exceed subtotal (caller is responsible for clamping)", () => {
      const p1 = new PercentageDiscountPolicy(80); // 80% of 100 = 80
      const p2 = new FixedAmountDiscountPolicy(80); // min(80, 100) = 80
      const composite = new CompositeDiscountPolicy([p1, p2], "sum");
      // sum mode: 80 + 80 = 160, which exceeds subtotal of 100
      expect(composite.computeDiscountCents(100)).toBe(160);
    });
  });

  describe("chain mode", () => {
    it("compounds discounts sequentially on remaining subtotal", () => {
      const p1 = new PercentageDiscountPolicy(50); // 50% of 1000 = 500
      const p2 = new PercentageDiscountPolicy(50); // 50% of 500 = 250
      const composite = new CompositeDiscountPolicy([p1, p2], "chain");
      expect(composite.computeDiscountCents(1000)).toBe(750);
    });

    it("order matters in chain mode", () => {
      const fixed = new FixedAmountDiscountPolicy(200);
      const pct = new PercentageDiscountPolicy(50);

      // Fixed first: 200 off 1000 = 800 remaining; then 50% of 800 = 400; total = 600
      const fixedFirst = new CompositeDiscountPolicy([fixed, pct], "chain");
      expect(fixedFirst.computeDiscountCents(1000)).toBe(600);

      // Percent first: 50% of 1000 = 500 remaining; then fixed 200; total = 700
      const pctFirst = new CompositeDiscountPolicy([pct, fixed], "chain");
      expect(pctFirst.computeDiscountCents(1000)).toBe(700);
    });

    it("never exceeds subtotal in chain mode", () => {
      const p1 = new FixedAmountDiscountPolicy(600);
      const p2 = new FixedAmountDiscountPolicy(600);
      const composite = new CompositeDiscountPolicy([p1, p2], "chain");
      // 600 off 1000 = 400 remaining; min(600, 400) = 400; total = 1000
      expect(composite.computeDiscountCents(1000)).toBe(1000);
    });

    it("returns 0 for zero subtotal", () => {
      const p1 = new PercentageDiscountPolicy(50);
      const composite = new CompositeDiscountPolicy([p1], "chain");
      expect(composite.computeDiscountCents(0)).toBe(0);
    });
  });

  describe("defaults to sum mode", () => {
    it("uses sum when mode is not specified", () => {
      const p1 = new FixedAmountDiscountPolicy(100);
      const p2 = new FixedAmountDiscountPolicy(100);
      const composite = new CompositeDiscountPolicy([p1, p2]);
      expect(composite.computeDiscountCents(1000)).toBe(200);
    });
  });
});

