+describe("Cart — async checkout", () => {
+  it("refreshes prices via priceFetcher", async () => {
+    const cart = new Cart();
+    cart.add(productA, 1);
+    const priceFetcher: PriceFetcher = {
+      fetchPriceCents: vi.fn().mockResolvedValue(1500),
+    };
+    const result = await cart.checkout({ priceFetcher });
+    expect(result.lines[0].product.unitPriceCents).toBe(1500);
+    expect(result.totals.subtotalCents).toBe(1500);
+  });
+
+  it("works without priceFetcher", async () => {
+    const cart = new Cart();
+    cart.add(productA, 2);
+    const result = await cart.checkout({});
+    expect(result.totals.subtotalCents).toBe(2000);
+  });
+
+  it("throws InventoryError when item unavailable", async () => {
+    const cart = new Cart();
+    cart.add(productA, 5);
+    const inventoryChecker: InventoryChecker = {
+      check: vi.fn().mockResolvedValue({ available: false, reason: "sold out" }),
+    };
+    try {
+      await cart.checkout({ inventoryChecker });
+      expect.fail("should have thrown");
+    } catch (e) {
+      expect(e).toBeInstanceOf(InventoryError);
+      const err = e as InventoryError;
+      expect(err.productId).toBe("a");
+      expect(err.requested).toBe(5);
+    }
+  });
+
+  it("throws InventoryError on partial-stock denial", async () => {
+    const cart = new Cart();
+    cart.add(productA, 10);
+    const inventoryChecker: InventoryChecker = {
+      check: vi.fn().mockResolvedValue({
+        available: true,
+        availableQuantity: 3,
+      }),
+    };
+    try {
+      await cart.checkout({ inventoryChecker });
+      expect.fail("should have thrown");
+    } catch (e) {
+      expect(e).toBeInstanceOf(InventoryError);
+      const err = e as InventoryError;
+      expect(err.available).toBe(3);
+      expect(err.requested).toBe(10);
+    }
+  });
+
+  it("passes inventory check when fully available", async () => {
+    const cart = new Cart();
+    cart.add(productA, 2);
+    const inventoryChecker: InventoryChecker = {
+      check: vi.fn().mockResolvedValue({ available: true }),
+    };
+    const result = await cart.checkout({ inventoryChecker });
+    expect(result.totals.subtotalCents).toBe(2000);
+  });
+
+  it("uses asyncTaxProvider for tax computation", async () => {
+    const discount: DiscountPolicy = { computeDiscountCents: () => 0 };
+    const cart = new Cart({ discountPolicy: discount });
+    cart.add(productA, 1); // subtotal 1000
+    const asyncTaxProvider: AsyncTaxRateProvider = {
+      getRate: vi.fn().mockResolvedValue(0.1),
+    };
+    const result = await cart.checkout({ asyncTaxProvider });
+    expect(result.totals.taxCents).toBe(100); // 10% of 1000
+  });
+
+  it("async tax applies after discount", async () => {
+    const discount: DiscountPolicy = { computeDiscountCents: () => 200 };
+    const cart = new Cart({ discountPolicy: discount });
+    cart.add(productA, 1); // subtotal 1000, discount 200, taxable 800
+    const asyncTaxProvider: AsyncTaxRateProvider = {
+      getRate: vi.fn().mockResolvedValue(0.1),
+    };
+    const result = await cart.checkout({ asyncTaxProvider });
+    expect(result.totals.taxCents).toBe(80); // 10% of 800
+  });
+
+  it("propagates asyncTaxProvider rejection", async () => {
+    const cart = new Cart();
+    cart.add(productA, 1);
+    const asyncTaxProvider: AsyncTaxRateProvider = {
+      getRate: vi.fn().mockRejectedValue(new Error("service down")),
+    };
+    await expect(cart.checkout({ asyncTaxProvider })).rejects.toThrow(
+      "service down",
+    );
+  });
+
+  it("full checkout with all collaborators", async () => {
+    const discount: DiscountPolicy = { computeDiscountCents: () => 100 };
+    const shipping: ShippingCalculator = {
+      computeShippingCents: () => 599,
+    };
+    const cart = new Cart({ discountPolicy: discount, shippingCalculator: shipping });
+    cart.add(productA, 1); // base price 1000
+
+    const priceFetcher: PriceFetcher = {
+      fetchPriceCents: vi.fn().mockResolvedValue(1200),
+    };
+    const inventoryChecker: InventoryChecker = {
+      check: vi.fn().mockResolvedValue({ available: true, availableQuantity: 10 }),
